intuition:
Think of the bundle as a small website with one map. The documents are the pages; the tickets are the map's nodes; and each `**Blocked by:**` line draws arrows into its ticket. Lay the nodes out in columns by how deep their dependencies go, and the shape of the work appears: what can start now, what waits, and what waits on what.

The graph is only as good as the lines it reads, so the page checks it against the rules `to-tickets` writes by. Try it: edit a `Blocked by` line below, or pick a broken case.

```figure Edit a ticket's Blocked by line and watch the frontier and the graph checks follow. This toy repeats the page's rules in a few lines.
<div class="fig">
  <div class="presets">
    <button data-p="written" class="on">As written</button>
    <button data-p="cycle">Add a cycle</button>
    <button data-p="missing">Name a missing ticket</button>
    <button data-p="later">Wait on a later ticket</button>
  </div>
  <div class="cols">
    <div class="rows" id="rows"></div>
    <div class="out"><svg id="edges"></svg><div id="graph"></div></div>
  </div>
  <div class="foot"><div id="front"></div><div id="checks"></div></div>
</div>
<style>
  .fig { font: 13.5px/1.5 var(--font-ui); color: var(--ink); }
  .presets { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 14px; }
  .presets button { font: inherit; font-size: 12.5px; border: 1px solid var(--line-2); background: var(--surface); color: var(--ink-2); border-radius: 99px; padding: 4px 11px; cursor: pointer; }
  .presets button.on { background: var(--ink); color: var(--bg); border-color: transparent; }
  .cols { display: grid; grid-template-columns: 250px 1fr; gap: 22px; align-items: start; }
  .row { display: grid; grid-template-columns: 26px 1fr; gap: 2px 8px; margin-bottom: 9px; }
  .row b { font: 650 12px var(--font-mono); color: var(--ink-2); padding-top: 6px; }
  .row span { font-weight: 600; font-size: 13px; }
  .row label { grid-column: 2; display: flex; align-items: center; gap: 6px; font-size: 11.5px; color: var(--ink-3); }
  .row input { flex: 1; min-width: 0; font: 12.5px var(--font-mono); padding: 4px 7px; border-radius: 7px; border: 1px solid var(--line-2); background: var(--surface-2); color: var(--ink); }
  .out { position: relative; min-height: 200px; }
  #edges { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
  #edges path { fill: none; stroke: var(--line-2); stroke-width: 1.6; }
  #edges path.bad { stroke: var(--fail); stroke-dasharray: 5 4; }
  .node { position: absolute; width: 112px; line-height: 1.3; padding: 7px 9px; border-radius: 10px; border: 1px solid var(--line); background: var(--surface); box-shadow: var(--shadow); font-size: 12px; transition: left .25s, top .25s; }
  .node i { font: normal 650 11px var(--font-mono); color: var(--ink-3); display: block; }
  .node.frontier { border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-bg); }
  .node.blocked { background: var(--surface-2); color: var(--ink-2); }
  .foot { display: grid; gap: 6px; margin-top: 12px; padding-top: 10px; border-top: 1px solid var(--line); font-size: 12.5px; }
  #checks div { color: var(--fail); } #checks .ok { color: var(--pass); font-weight: 600; }
</style>
<script>
  const TITLES = { 1: "Challenger pass", 2: "Trap puzzles", 3: "Benchmark runner", 4: "First benchmark run" };
  const PRESETS = {
    written: { 1: "", 2: "", 3: "01, 02", 4: "03" },
    cycle: { 1: "", 2: "04", 3: "01, 02", 4: "03" },
    missing: { 1: "", 2: "", 3: "01, 02, 07", 4: "03" },
    later: { 1: "", 2: "", 3: "01, 04", 4: "02" },
  };
  let by = { ...PRESETS.written };
  const pad = (n) => String(n).padStart(2, "0");
  const rows = document.getElementById("rows");
  function drawRows() {
    rows.innerHTML = Object.keys(TITLES).map((id) => `<div class="row"><b>${pad(id)}</b><span>${TITLES[id]}</span><label>Blocked by <input data-id="${id}" value="${by[id]}" placeholder="none"></label></div>`).join("");
  }
  function draw() {
    const ids = Object.keys(TITLES).map(Number);
    const named = Object.fromEntries(ids.map((id) => [id, [...new Set((by[id].match(/\d{2,3}/g) || []).map(Number))]]));
    const blockers = Object.fromEntries(ids.map((id) => [id, named[id].filter((n) => ids.includes(n))]));
    const depth = {}, visiting = new Set();
    const d = (id) => { if (id in depth) return depth[id]; if (visiting.has(id)) return 0; visiting.add(id); const v = blockers[id].length ? 1 + Math.max(...blockers[id].map(d)) : 0; visiting.delete(id); return (depth[id] = v); };
    ids.forEach(d);
    const cols = {}; ids.forEach((id) => (cols[depth[id]] ??= []).push(id));
    const ncols = Object.keys(cols).length, width = document.querySelector(".out").clientWidth || 380;
    const step = ncols > 1 ? Math.min(150, (width - 112) / (ncols - 1)) : 0;
    const pos = {}; Object.entries(cols).forEach(([c, list]) => list.forEach((id, r) => (pos[id] = { x: c * step, y: r * 64 + (Math.max(...Object.values(cols).map((l) => l.length)) - list.length) * 32 })));
    const problems = [];
    ids.forEach((id) => named[id].filter((n) => !ids.includes(n)).forEach((n) => problems.push(`${pad(id)} waits on ${pad(n)}, which is not a ticket here.`)));
    ids.forEach((id) => blockers[id].filter((b) => b > id).forEach((b) => problems.push(`${pad(id)} waits on a later ticket, ${pad(b)}.`)));
    const state = {}; const walk = (id, path) => { state[id] = 1; for (const b of blockers[id]) { if (state[b] === 1) problems.push(`Cycle: ${[...path.slice(path.indexOf(b)), b].map(pad).join(" → ")}.`); else if (!state[b]) walk(b, [...path, b]); } state[id] = 2; };
    ids.forEach((id) => state[id] || walk(id, [id]));
    const frontier = ids.filter((id) => named[id].length === blockers[id].length && blockers[id].length === 0);
    document.getElementById("graph").innerHTML = ids.map((id) => `<div class="node ${frontier.includes(id) ? "frontier" : "blocked"}" style="left:${pos[id].x}px;top:${pos[id].y}px"><i>${pad(id)}</i>${TITLES[id]}</div>`).join("");
    document.getElementById("edges").innerHTML = ids.flatMap((id) => blockers[id].map((b) => { const p = pos[b], q = pos[id]; const x1 = p.x + 112, y1 = p.y + 22, x2 = q.x, y2 = q.y + 22; const back = x2 <= x1; return `<path class="${back || b > id ? "bad" : ""}" d="${back ? `M${x1} ${y1} C${x1 + 50} ${y1 + 90}, ${x2 - 50} ${y2 + 90}, ${x2} ${y2}` : `M${x1} ${y1} C${x1 + 20} ${y1}, ${x2 - 20} ${y2}, ${x2} ${y2}`}"/>`; })).join("");
    document.getElementById("front").innerHTML = `<b>Can start now:</b> ${frontier.length ? frontier.map(pad).join(", ") : "nothing"}`;
    document.getElementById("checks").innerHTML = problems.length ? problems.map((p) => `<div>${p}</div>`).join("") : '<span class="ok">✓ Graph checks pass</span>';
  }
  rows.addEventListener("input", (e) => { by[e.target.dataset.id] = e.target.value; draw(); });
  document.querySelector(".presets").addEventListener("click", (e) => {
    const p = e.target.dataset.p; if (!p) return;
    by = { ...PRESETS[p] };
    document.querySelectorAll(".presets button").forEach((b) => b.classList.toggle("on", b === e.target));
    drawRows(); draw();
  });
  drawRows(); draw();
  new ResizeObserver(draw).observe(document.querySelector(".out"));
</script>
```

> [!NOTE]
> A ticket that waits on a missing ticket counts as **blocked**, not ready. The page cannot know that the missing ticket is done, so it must not offer the work as startable.

Everything that is not Markdown is **evidence**: records, logs, prototypes. A bundle can hold hundreds of them, and the reviewer opens a few at most. So the page lists them by name and size, and asks the server for a file only when the reviewer opens it:

```mermaid
sequenceDiagram
  participant P as Page
  participant S as Page server
  participant D as Bundle on disk
  P->>S: GET /file?path=evidence/run.json (with the token)
  S->>S: Is this path on the page's own list?
  S->>D: read the file
  D-->>S: bytes
  S->>S: not text? say so. Text? highlight it, keep the lines on the page
  S-->>P: { lines }
```

> [!IMPORTANT]
> The server answers only paths from the list it built itself. The page cannot name a file outside the bundle, so a token in the wrong hands cannot read the rest of the disk.
